const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const CUT_GUIDES='ABCDEFGHIJK'.split('');
export function sharingLoafArt(pieces,cuts,{guides=false,label='One whole rectangular moon-loaf'}={}){
 return `<svg class="sc-loaf-art" viewBox="0 0 600 205" role="img" aria-label="${esc(label)}. ${pieces.map(p=>`Piece ${p.index+1}${p.selected?' marked packed':''}`).join('; ')}"><rect x="25" y="20" width="550" height="165" rx="24" fill="#e8efdd"/><text x="300" y="39" text-anchor="middle" font-size="17" fill="#183f39">One whole loaf</text>${guides?CUT_GUIDES.map((g,i)=>`<path d="M${60+(i+1)*40} 50V153" stroke="#9caa90" stroke-dasharray="3 4"/><text x="${60+(i+1)*40}" y="174" text-anchor="middle" font-size="16" fill="#4a654a">${g}</text>`).join(''):''}${pieces.map(p=>`<rect x="${60+p.start*40}" y="62" width="${p.width*40}" height="82" fill="${p.selected?'#9cbea1':'#efd8a8'}"/><text x="${60+(p.start+p.width/2)*40}" y="110" text-anchor="middle" font-size="19" font-weight="700" fill="#183f39">${p.index+1}${p.selected?' ✓':''}</text>`).join('')}<rect x="60" y="62" width="480" height="82" fill="none" stroke="#815d37" stroke-width="3"/>${cuts.map(n=>`<path d="M${60+n*40} 57V149" stroke="#183f39" stroke-width="4"/>`).join('')}</svg>`;
}
export function sharingNumberLine(position){const x=40+320*position;return `<svg class="sc-number-line" viewBox="0 0 400 105" role="img" aria-label="How much is packed: ${{0:'none',.25:'one quarter',.5:'one half',.75:'three quarters',1:'one whole'}[position]||'a part'} of the original loaf. Fixed number line from zero to one whole."><rect x="40" y="15" width="320" height="18" fill="#efe4ca"/><rect x="40" y="15" width="${320*position}" height="18" fill="#397958"/><path d="M40 61H360" stroke="#183f39" stroke-width="2"/>${[['0',0],['¼',.25],['½',.5],['¾',.75],['1 whole',1]].map(([label,f])=>`<path d="M${40+320*f} 55V68" stroke="#183f39" stroke-width="2"/><text x="${40+320*f}" y="91" text-anchor="middle" fill="#183f39" font-size="15">${label}</text>`).join('')}<path d="M${x} 40l-7 12h14Z" fill="#c78929"/></svg>`;}
const POSITIONS=[[23,36],[68,23],[116,40],[43,76],[96,84],[146,77],[15,111],[68,122],[119,121],[157,28],[169,116],[83,58]];
export function sharingBunArt(count,label='Buns'){
 return `<svg class="sc-bun-art" viewBox="0 0 195 145" role="img" aria-label="${count} identical ${esc(label.toLowerCase())}">${POSITIONS.slice(0,count).map(([x,y],i)=>`<g aria-hidden="true"><ellipse cx="${x}" cy="${y}" rx="13" ry="10" fill="#e6b66b" stroke="#845b32" stroke-width="1.5"/><path d="M${x-6} ${y-3}q5-5 10 0M${x-5} ${y+1}q5-4 10 0" fill="none" stroke="#fff3cc" stroke-width="2"/></g>`).join('')}</svg>`;
}
export function sharingEquivalenceArt(step){const halves=[{index:0,start:0,end:6,width:6,selected:step>0},{index:1,start:6,end:12,width:6,selected:false}],quarters=Array.from({length:4},(_,i)=>({index:i,start:i*3,end:(i+1)*3,width:3,selected:step>0&&i<2}));return `<div class="sc-equivalence"><div><strong>Two equal shares of one loaf</strong>${sharingLoafArt(halves,[6])}</div><div><strong>Four equal shares of the identical whole</strong>${sharingLoafArt(quarters,[3,6,9])}</div>${step>1?'<p class="sc-equation">1/2 = 2/4 <span>One half is the same amount as two quarters of this same whole.</span></p>':''}</div>`;}
